#include <stdio.h>
#include <stdlib.h>
struct node {
    int data;
    struct node *next;
};

int main() {
    struct node *head = (struct node *)malloc(sizeof(struct node));
    if (head == NULL) {
        perror("Memory allocation failed");
        return 1;
    }
    head->data = 10;
    head->next = NULL;

    struct node *p = head;
    struct node *temp;

    while (p != NULL) {
        temp = p;
        p = p->next;
        free(temp);
    }
    return 0;
}
